static
void kernel_2mm(int ni, int nj, int nk, int nl,
		DATA_TYPE alpha,
		DATA_TYPE beta,
		DATA_TYPE POLYBENCH_2D(tmp,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(C,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(D,NI,NL,ni,nl))
{
  int i, j, k;

#pragma scop

  for (i = 0; i < _PB_NI; i++)
    for (j = 0; j < _PB_NJ; j++)
      {
        DATA_TYPE sum = SCALAR_VAL(0.0);
        for (k = 0; k < _PB_NK; ++k)
          sum += alpha * A[i][k] * B[k][j];
        tmp[i][j] = sum;
      }

  for (i = 0; i < _PB_NI; i++)
    for (j = 0; j < _PB_NL; j++)
      {
        DATA_TYPE sum = D[i][j] * beta;
        for (k = 0; k < _PB_NJ; ++k)
          sum += tmp[i][k] * C[k][j];
        D[i][j] = sum;
      }

#pragma endscop

}

static
void kernel_3mm(int ni, int nj, int nk, int nl, int nm,
		DATA_TYPE POLYBENCH_2D(E,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(F,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(C,NJ,NM,nj,nm),
		DATA_TYPE POLYBENCH_2D(D,NM,NL,nm,nl),
		DATA_TYPE POLYBENCH_2D(G,NI,NL,ni,nl))
{
  int i, j, k;

#pragma scop

#if defined(__riscv_vector) && !defined(__cplusplus)
  if (sizeof(DATA_TYPE) == sizeof(float)) {
    float (*e)[nj] = (float (*)[nj])E;
    float (*a)[nk] = (float (*)[nk])A;
    float (*b)[nj] = (float (*)[nj])B;
    float (*f)[nl] = (float (*)[nl])F;
    float (*c)[nm] = (float (*)[nm])C;
    float (*d)[nl] = (float (*)[nl])D;
    float (*g)[nl] = (float (*)[nl])G;

    for (i = 0; i < _PB_NI; i++) {
      for (j = 0; j < _PB_NJ; ) {
        size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_NJ - j));
        vfloat32m1_t acc = __riscv_vfmv_v_f_f32m1(0.0f, vl);
        for (k = 0; k < _PB_NK; ++k) {
          vfloat32m1_t vb = __riscv_vle32_v_f32m1(&b[k][j], vl);
          acc = __riscv_vfmacc_vf_f32m1(acc, a[i][k], vb, vl);
        }
        __riscv_vse32_v_f32m1(&e[i][j], acc, vl);
        j += (int)vl;
      }
    }

    for (i = 0; i < _PB_NJ; i++) {
      for (j = 0; j < _PB_NL; ) {
        size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_NL - j));
        vfloat32m1_t acc = __riscv_vfmv_v_f_f32m1(0.0f, vl);
        for (k = 0; k < _PB_NM; ++k) {
          vfloat32m1_t vd = __riscv_vle32_v_f32m1(&d[k][j], vl);
          acc = __riscv_vfmacc_vf_f32m1(acc, c[i][k], vd, vl);
        }
        __riscv_vse32_v_f32m1(&f[i][j], acc, vl);
        j += (int)vl;
      }
    }

    for (i = 0; i < _PB_NI; i++) {
      for (j = 0; j < _PB_NL; ) {
        size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_NL - j));
        vfloat32m1_t acc = __riscv_vfmv_v_f_f32m1(0.0f, vl);
        for (k = 0; k < _PB_NJ; ++k) {
          vfloat32m1_t vf = __riscv_vle32_v_f32m1(&f[k][j], vl);
          acc = __riscv_vfmacc_vf_f32m1(acc, e[i][k], vf, vl);
        }
        __riscv_vse32_v_f32m1(&g[i][j], acc, vl);
        j += (int)vl;
      }
    }
  } else if (sizeof(DATA_TYPE) == sizeof(double)) {
    double (*e)[nj] = (double (*)[nj])E;
    double (*a)[nk] = (double (*)[nk])A;
    double (*b)[nj] = (double (*)[nj])B;
    double (*f)[nl] = (double (*)[nl])F;
    double (*c)[nm] = (double (*)[nm])C;
    double (*d)[nl] = (double (*)[nl])D;
    double (*g)[nl] = (double (*)[nl])G;

    for (i = 0; i < _PB_NI; i++) {
      for (j = 0; j < _PB_NJ; ) {
        size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_NJ - j));
        vfloat64m1_t acc = __riscv_vfmv_v_f_f64m1(0.0, vl);
        for (k = 0; k < _PB_NK; ++k) {
          vfloat64m1_t vb = __riscv_vle64_v_f64m1(&b[k][j], vl);
          acc = __riscv_vfmacc_vf_f64m1(acc, a[i][k], vb, vl);
        }
        __riscv_vse64_v_f64m1(&e[i][j], acc, vl);
        j += (int)vl;
      }
    }

    for (i = 0; i < _PB_NJ; i++) {
      for (j = 0; j < _PB_NL; ) {
        size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_NL - j));
        vfloat64m1_t acc = __riscv_vfmv_v_f_f64m1(0.0, vl);
        for (k = 0; k < _PB_NM; ++k) {
          vfloat64m1_t vd = __riscv_vle64_v_f64m1(&d[k][j], vl);
          acc = __riscv_vfmacc_vf_f64m1(acc, c[i][k], vd, vl);
        }
        __riscv_vse64_v_f64m1(&f[i][j], acc, vl);
        j += (int)vl;
      }
    }

    for (i = 0; i < _PB_NI; i++) {
      for (j = 0; j < _PB_NL; ) {
        size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_NL - j));
        vfloat64m1_t acc = __riscv_vfmv_v_f_f64m1(0.0, vl);
        for (k = 0; k < _PB_NJ; ++k) {
          vfloat64m1_t vf = __riscv_vle64_v_f64m1(&f[k][j], vl);
          acc = __riscv_vfmacc_vf_f64m1(acc, e[i][k], vf, vl);
        }
        __riscv_vse64_v_f64m1(&g[i][j], acc, vl);
        j += (int)vl;
      }
    }
  } else
#endif
  {
    for (i = 0; i < _PB_NI; i++)
      for (j = 0; j < _PB_NJ; j++)
      {
	E[i][j] = SCALAR_VAL(0.0);
	for (k = 0; k < _PB_NK; ++k)
	  E[i][j] += A[i][k] * B[k][j];
      }

    for (i = 0; i < _PB_NJ; i++)
      for (j = 0; j < _PB_NL; j++)
      {
	F[i][j] = SCALAR_VAL(0.0);
	for (k = 0; k < _PB_NM; ++k)
	  F[i][j] += C[i][k] * D[k][j];
      }

    for (i = 0; i < _PB_NI; i++)
      for (j = 0; j < _PB_NL; j++)
      {
	G[i][j] = SCALAR_VAL(0.0);
	for (k = 0; k < _PB_NJ; ++k)
	  G[i][j] += E[i][k] * F[k][j];
      }
  }

#pragma endscop

}

#ifndef DATA_TYPE
#define DATA_TYPE double
#endif

#ifndef N
#define N 1024
#endif

#ifndef TSTEPS
#define TSTEPS 500
#endif

#ifndef _PB_N
#define _PB_N n
#endif

#ifndef _PB_TSTEPS
#define _PB_TSTEPS tsteps
#endif

#ifndef SCALAR_VAL
#define SCALAR_VAL(x) ((DATA_TYPE)(x))
#endif

#ifndef POLYBENCH_2D
#define POLYBENCH_2D(var, dim1, dim2, n1, n2) var[dim1][dim2]
#endif

static
void kernel_adi(int tsteps, int n,
		DATA_TYPE POLYBENCH_2D(u,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(v,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(p,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(q,N,N,n,n))
{
  int t, i, j;
  DATA_TYPE DX, DY, DT;
  DATA_TYPE B1, B2;
  DATA_TYPE mul1, mul2;
  DATA_TYPE a, b, c, d, e, f;

#pragma scop

  DX = SCALAR_VAL(1.0)/(DATA_TYPE)_PB_N;
  DY = SCALAR_VAL(1.0)/(DATA_TYPE)_PB_N;
  DT = SCALAR_VAL(1.0)/(DATA_TYPE)_PB_TSTEPS;
  B1 = SCALAR_VAL(2.0);
  B2 = SCALAR_VAL(1.0);
  mul1 = B1 * DT / (DX * DX);
  mul2 = B2 * DT / (DY * DY);

  a = -mul1 / SCALAR_VAL(2.0);
  b = SCALAR_VAL(1.0) + mul1;
  c = a;
  d = -mul2 / SCALAR_VAL(2.0);
  e = SCALAR_VAL(1.0) + mul2;
  f = d;

  {
    const DATA_TYPE one = SCALAR_VAL(1.0);
    const DATA_TYPE zero = SCALAR_VAL(0.0);
    const DATA_TYPE one_plus_2d = SCALAR_VAL(1.0) + SCALAR_VAL(2.0) * d;
    const DATA_TYPE one_plus_2a = SCALAR_VAL(1.0) + SCALAR_VAL(2.0) * a;
    const int n1 = _PB_N - 1;
    const int n2 = _PB_N - 2;

    for (t = 1; t <= _PB_TSTEPS; t++) {

      for (i = 1; i < n1; i++) {
        DATA_TYPE * __restrict pi = &p[i][0];
        DATA_TYPE * __restrict qi = &q[i][0];

        v[0][i] = one;
        pi[0] = zero;
        qi[0] = v[0][i];

        {
          DATA_TYPE p_prev = pi[0];
          DATA_TYPE q_prev = qi[0];

          for (j = 1; j < n1; j++) {
            const DATA_TYPE denom = a * p_prev + b;
            const DATA_TYPE p_cur = -c / denom;
            const DATA_TYPE q_cur =
              (-d * u[j][i-1]
               + one_plus_2d * u[j][i]
               - f * u[j][i+1]
               - a * q_prev) / denom;

            pi[j] = p_cur;
            qi[j] = q_cur;
            p_prev = p_cur;
            q_prev = q_cur;
          }
        }

        v[n1][i] = one;
        for (j = n2; j >= 1; j--) {
          v[j][i] = pi[j] * v[j+1][i] + qi[j];
        }
      }

      for (i = 1; i < n1; i++) {
        DATA_TYPE * __restrict ui = &u[i][0];
        DATA_TYPE * __restrict pi = &p[i][0];
        DATA_TYPE * __restrict qi = &q[i][0];

        ui[0] = one;
        pi[0] = zero;
        qi[0] = ui[0];

        {
          DATA_TYPE p_prev = pi[0];
          DATA_TYPE q_prev = qi[0];

          for (j = 1; j < n1; j++) {
            const DATA_TYPE denom = d * p_prev + e;
            const DATA_TYPE p_cur = -f / denom;
            const DATA_TYPE q_cur =
              (-a * v[i-1][j]
               + one_plus_2a * v[i][j]
               - c * v[i+1][j]
               - d * q_prev) / denom;

            pi[j] = p_cur;
            qi[j] = q_cur;
            p_prev = p_cur;
            q_prev = q_cur;
          }
        }

        ui[n1] = one;
        for (j = n2; j >= 1; j--) {
          ui[j] = pi[j] * ui[j+1] + qi[j];
        }
      }
    }
  }

#pragma endscop
}

static
void kernel_atax(int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n),
		 DATA_TYPE POLYBENCH_1D(y,N,n),
		 DATA_TYPE POLYBENCH_1D(tmp,M,m))
{
  int i, j;

#pragma scop
#if defined(__riscv_vector) && defined(DATA_TYPE_IS_DOUBLE)
  for (j = 0; j < _PB_N; )
  {
    size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_N - j));
    vfloat64m1_t vz = __riscv_vfmv_v_f_f64m1((double)0.0, vl);
    __riscv_vse64_v_f64m1((double *)&y[j], vz, vl);
    j += (int)vl;
  }

  for (i = 0; i < _PB_M; i++)
  {
    DATA_TYPE sum = SCALAR_VAL(0.0);
    DATA_TYPE *Ai = &A[i][0];

    for (j = 0; j < _PB_N; )
    {
      size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_N - j));
      vfloat64m1_t va = __riscv_vle64_v_f64m1((const double *)&Ai[j], vl);
      vfloat64m1_t vx = __riscv_vle64_v_f64m1((const double *)&x[j], vl);
      vfloat64m1_t vacc = __riscv_vfmv_v_f_f64m1((double)0.0, vl);
      vacc = __riscv_vfmacc_vv_f64m1(vacc, va, vx, vl);
      vfloat64m1_t vred = __riscv_vfredusum_vs_f64m1_f64m1(
          vacc, __riscv_vfmv_v_f_f64m1((double)0.0, vl), vl);
      sum += (DATA_TYPE)__riscv_vfmv_f_s_f64m1_f64(vred);
      j += (int)vl;
    }

    tmp[i] = sum;

    for (j = 0; j < _PB_N; )
    {
      size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_N - j));
      vfloat64m1_t va = __riscv_vle64_v_f64m1((const double *)&Ai[j], vl);
      vfloat64m1_t vy = __riscv_vle64_v_f64m1((const double *)&y[j], vl);
      vy = __riscv_vfmacc_vf_f64m1(vy, (double)sum, va, vl);
      __riscv_vse64_v_f64m1((double *)&y[j], vy, vl);
      j += (int)vl;
    }
  }

#elif defined(__riscv_vector) && defined(DATA_TYPE_IS_FLOAT)
  for (j = 0; j < _PB_N; )
  {
    size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_N - j));
    vfloat32m1_t vz = __riscv_vfmv_v_f_f32m1((float)0.0f, vl);
    __riscv_vse32_v_f32m1((float *)&y[j], vz, vl);
    j += (int)vl;
  }

  for (i = 0; i < _PB_M; i++)
  {
    DATA_TYPE sum = SCALAR_VAL(0.0);
    DATA_TYPE *Ai = &A[i][0];

    for (j = 0; j < _PB_N; )
    {
      size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_N - j));
      vfloat32m1_t va = __riscv_vle32_v_f32m1((const float *)&Ai[j], vl);
      vfloat32m1_t vx = __riscv_vle32_v_f32m1((const float *)&x[j], vl);
      vfloat32m1_t vacc = __riscv_vfmv_v_f_f32m1((float)0.0f, vl);
      vacc = __riscv_vfmacc_vv_f32m1(vacc, va, vx, vl);
      vfloat32m1_t vred = __riscv_vfredusum_vs_f32m1_f32m1(
          vacc, __riscv_vfmv_v_f_f32m1((float)0.0f, vl), vl);
      sum += (DATA_TYPE)__riscv_vfmv_f_s_f32m1_f32(vred);
      j += (int)vl;
    }

    tmp[i] = sum;

    for (j = 0; j < _PB_N; )
    {
      size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_N - j));
      vfloat32m1_t va = __riscv_vle32_v_f32m1((const float *)&Ai[j], vl);
      vfloat32m1_t vy = __riscv_vle32_v_f32m1((const float *)&y[j], vl);
      vy = __riscv_vfmacc_vf_f32m1(vy, (float)sum, va, vl);
      __riscv_vse32_v_f32m1((float *)&y[j], vy, vl);
      j += (int)vl;
    }
  }

#else
  for (i = 0; i < _PB_N; i++)
    y[i] = 0;

  for (i = 0; i < _PB_M; i++)
  {
    DATA_TYPE *Ai = &A[i][0];
    DATA_TYPE sum = SCALAR_VAL(0.0);

    for (j = 0; j < _PB_N; j++)
      sum = sum + Ai[j] * x[j];

    tmp[i] = sum;

    for (j = 0; j < _PB_N; j++)
      y[j] = y[j] + Ai[j] * sum;
  }
#endif
#pragma endscop

}

static
void kernel_bicg(int m, int n,
                 DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
                 DATA_TYPE POLYBENCH_1D(s,M,m),
                 DATA_TYPE POLYBENCH_1D(q,N,n),
                 DATA_TYPE POLYBENCH_1D(p,M,m),
                 DATA_TYPE POLYBENCH_1D(r,N,n))
{
  int i, j;

#pragma scop
  for (i = 0; i < _PB_M; i++)
    s[i] = SCALAR_VAL(0.0);

#if defined(__riscv_vector) && defined(DATA_TYPE_IS_FLOAT)
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE qi = SCALAR_VAL(0.0);
    DATA_TYPE ri = r[i];
    DATA_TYPE *a_row = &A[i][0];
    j = 0;

    while (j < _PB_M) {
      size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_M - j));
      vfloat32m1_t va = __riscv_vle32_v_f32m1(&a_row[j], vl);
      vfloat32m1_t vp = __riscv_vle32_v_f32m1(&p[j], vl);
      vfloat32m1_t vs = __riscv_vle32_v_f32m1(&s[j], vl);
      vfloat32m1_t vacc = __riscv_vfmul_vf_f32m1(va, ri, vl);

      vs = __riscv_vfadd_vv_f32m1(vs, vacc, vl);
      __riscv_vse32_v_f32m1(&s[j], vs, vl);

      qi += __riscv_vfmv_f_s_f32m1_f32(
              __riscv_vfredusum_vs_f32m1_f32m1(
                __riscv_vfmul_vv_f32m1(va, vp, vl),
                __riscv_vfmv_v_f_f32m1(0.0f, 1),
                __riscv_vfmv_v_f_f32m1(0.0f, vl),
                vl));

      j += (int)vl;
    }

    q[i] = qi;
  }

#elif defined(__riscv_vector) && defined(DATA_TYPE_IS_DOUBLE)
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE qi = SCALAR_VAL(0.0);
    DATA_TYPE ri = r[i];
    DATA_TYPE *a_row = &A[i][0];
    j = 0;

    while (j < _PB_M) {
      size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_M - j));
      vfloat64m1_t va = __riscv_vle64_v_f64m1(&a_row[j], vl);
      vfloat64m1_t vp = __riscv_vle64_v_f64m1(&p[j], vl);
      vfloat64m1_t vs = __riscv_vle64_v_f64m1(&s[j], vl);
      vfloat64m1_t vacc = __riscv_vfmul_vf_f64m1(va, ri, vl);

      vs = __riscv_vfadd_vv_f64m1(vs, vacc, vl);
      __riscv_vse64_v_f64m1(&s[j], vs, vl);

      qi += __riscv_vfmv_f_s_f64m1_f64(
              __riscv_vfredusum_vs_f64m1_f64m1(
                __riscv_vfmul_vv_f64m1(va, vp, vl),
                __riscv_vfmv_v_f_f64m1(0.0, 1),
                __riscv_vfmv_v_f_f64m1(0.0, vl),
                vl));

      j += (int)vl;
    }

    q[i] = qi;
  }

#else
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE qi = SCALAR_VAL(0.0);
    DATA_TYPE ri = r[i];
    DATA_TYPE *a_row = &A[i][0];

    for (j = 0; j < _PB_M; j++) {
      DATA_TYPE aij = a_row[j];
      s[j] = s[j] + ri * aij;
      qi = qi + aij * p[j];
    }
    q[i] = qi;
  }
#endif
#pragma endscop
}

static
void kernel_cholesky(int n,
		     DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_N; i++) {

    DATA_TYPE *Ai = A[i];

    for (j = 0; j < i; j++) {
      DATA_TYPE sum = Ai[j];
      DATA_TYPE *Aj = A[j];
      int kk = 0;

#if defined(__riscv_vector) && !defined(__cplusplus)
#if defined(DATA_TYPE_IS_FLOAT)
      while (kk < j) {
        size_t vl = __riscv_vsetvl_e32m1((size_t)(j - kk));
        vfloat32m1_t vi = __riscv_vle32_v_f32m1((const float *)(Ai + kk), vl);
        vfloat32m1_t vj = __riscv_vle32_v_f32m1((const float *)(Aj + kk), vl);
        vfloat32m1_t vm = __riscv_vfmul_vv_f32m1(vi, vj, vl);
        vfloat32m1_t vs = __riscv_vfredusum_vs_f32m1_f32m1(
            vm, __riscv_vfmv_v_f_f32m1(0.0f, vl), vl);
        sum -= (DATA_TYPE)__riscv_vfmv_f_s_f32m1_f32(vs);
        kk += (int)vl;
      }
#elif defined(DATA_TYPE_IS_DOUBLE)
      while (kk < j) {
        size_t vl = __riscv_vsetvl_e64m1((size_t)(j - kk));
        vfloat64m1_t vi = __riscv_vle64_v_f64m1((const double *)(Ai + kk), vl);
        vfloat64m1_t vj = __riscv_vle64_v_f64m1((const double *)(Aj + kk), vl);
        vfloat64m1_t vm = __riscv_vfmul_vv_f64m1(vi, vj, vl);
        vfloat64m1_t vs = __riscv_vfredusum_vs_f64m1_f64m1(
            vm, __riscv_vfmv_v_f_f64m1(0.0, vl), vl);
        sum -= (DATA_TYPE)__riscv_vfmv_f_s_f64m1_f64(vs);
        kk += (int)vl;
      }
#endif
#endif

      for (; kk < j; kk++) {
        sum -= Ai[kk] * Aj[kk];
      }
      Ai[j] = sum / Aj[j];
    }

    {
      DATA_TYPE sum = Ai[i];
      int kk = 0;

#if defined(__riscv_vector) && !defined(__cplusplus)
#if defined(DATA_TYPE_IS_FLOAT)
      while (kk < i) {
        size_t vl = __riscv_vsetvl_e32m1((size_t)(i - kk));
        vfloat32m1_t vi = __riscv_vle32_v_f32m1((const float *)(Ai + kk), vl);
        vfloat32m1_t vm = __riscv_vfmul_vv_f32m1(vi, vi, vl);
        vfloat32m1_t vs = __riscv_vfredusum_vs_f32m1_f32m1(
            vm, __riscv_vfmv_v_f_f32m1(0.0f, vl), vl);
        sum -= (DATA_TYPE)__riscv_vfmv_f_s_f32m1_f32(vs);
        kk += (int)vl;
      }
#elif defined(DATA_TYPE_IS_DOUBLE)
      while (kk < i) {
        size_t vl = __riscv_vsetvl_e64m1((size_t)(i - kk));
        vfloat64m1_t vi = __riscv_vle64_v_f64m1((const double *)(Ai + kk), vl);
        vfloat64m1_t vm = __riscv_vfmul_vv_f64m1(vi, vi, vl);
        vfloat64m1_t vs = __riscv_vfredusum_vs_f64m1_f64m1(
            vm, __riscv_vfmv_v_f_f64m1(0.0, vl), vl);
        sum -= (DATA_TYPE)__riscv_vfmv_f_s_f64m1_f64(vs);
        kk += (int)vl;
      }
#endif
#endif

      for (; kk < i; kk++) {
        sum -= Ai[kk] * Ai[kk];
      }
      Ai[i] = SQRT_FUN(sum);
    }
  }
#pragma endscop

}

static
void kernel_correlation(int m, int n,
			typeof(float_n) float_n,
			typeof(*mean) mean,
			typeof(*stddev) stddev,
			typeof(*data) data,
			typeof(*corr) corr)
{
  int i, j, k;
  typeof(float_n) eps = SCALAR_VAL(0.1);
  typeof(float_n) sqrt_float_n = SQRT_FUN(float_n);

#pragma scop
  for (j = 0; j < _PB_M; j++)
    {
      typeof(float_n) sum = SCALAR_VAL(0.0);
      for (i = 0; i < _PB_N; i++)
	sum += data[i][j];
      mean[j] = sum / float_n;
    }

  for (j = 0; j < _PB_M; j++)
    {
      typeof(float_n) sum = SCALAR_VAL(0.0);
      typeof(float_n) mj = mean[j];
      for (i = 0; i < _PB_N; i++)
        {
          typeof(float_n) d = data[i][j] - mj;
          sum += d * d;
        }
      stddev[j] = sum / float_n;
      stddev[j] = SQRT_FUN(stddev[j]);
      stddev[j] = stddev[j] <= eps ? SCALAR_VAL(1.0) : stddev[j];
    }

  for (i = 0; i < _PB_N; i++)
    {
      for (j = 0; j < _PB_M; j++)
        data[i][j] = (data[i][j] - mean[j]) / (sqrt_float_n * stddev[j]);
    }

  for (i = 0; i < _PB_M - 1; i++)
    {
      corr[i][i] = SCALAR_VAL(1.0);
      for (j = i + 1; j < _PB_M; j++)
        {
          typeof(float_n) sum = SCALAR_VAL(0.0);
          for (k = 0; k < _PB_N; k++)
            sum += data[k][i] * data[k][j];
          corr[i][j] = sum;
          corr[j][i] = sum;
        }
    }
  corr[_PB_M - 1][_PB_M - 1] = SCALAR_VAL(1.0);
#pragma endscop

}

