static
void kernel_deriche(int w, int h, DATA_TYPE alpha,
       DATA_TYPE POLYBENCH_2D(imgIn, W, H, w, h),
       DATA_TYPE POLYBENCH_2D(imgOut, W, H, w, h),
       DATA_TYPE POLYBENCH_2D(y1, W, H, w, h),
       DATA_TYPE POLYBENCH_2D(y2, W, H, w, h)) {
    int i, j;
    DATA_TYPE xm1, tm1, ym1, ym2;
    DATA_TYPE xp1, xp2;
    DATA_TYPE tp1, tp2;
    DATA_TYPE yp1, yp2;

    DATA_TYPE k;
    DATA_TYPE a1, a2, a3, a4, a5, a6, a7, a8;
    DATA_TYPE b1, b2, c1, c2;

#pragma scop
    {
        const DATA_TYPE exp_m_alpha = EXP_FUN(-alpha);
        const DATA_TYPE exp_m_2alpha = EXP_FUN(SCALAR_VAL(-2.0) * alpha);
        const DATA_TYPE exp_p_2alpha = EXP_FUN(SCALAR_VAL(2.0) * alpha);

        k = (SCALAR_VAL(1.0) - exp_m_alpha) * (SCALAR_VAL(1.0) - exp_m_alpha) /
            (SCALAR_VAL(1.0) + SCALAR_VAL(2.0) * alpha * exp_m_alpha - exp_p_2alpha);
        a1 = a5 = k;
        a2 = a6 = k * exp_m_alpha * (alpha - SCALAR_VAL(1.0));
        a3 = a7 = k * exp_m_alpha * (alpha + SCALAR_VAL(1.0));
        a4 = a8 = -k * exp_m_2alpha;
        b1 = POW_FUN(SCALAR_VAL(2.0), -alpha);
        b2 = -exp_m_2alpha;
        c1 = c2 = SCALAR_VAL(1.0);
    }

    for (i = 0; i < _PB_W; i++) {
        DATA_TYPE *in_row = &imgIn[i][0];
        DATA_TYPE *y1_row = &y1[i][0];

        ym1 = SCALAR_VAL(0.0);
        ym2 = SCALAR_VAL(0.0);
        xm1 = SCALAR_VAL(0.0);

        for (j = 0; j < _PB_H; j++) {
            const DATA_TYPE x0 = in_row[j];
            const DATA_TYPE yv = a1 * x0 + a2 * xm1 + b1 * ym1 + b2 * ym2;
            y1_row[j] = yv;
            xm1 = x0;
            ym2 = ym1;
            ym1 = yv;
        }
    }

    for (i = 0; i < _PB_W; i++) {
        DATA_TYPE *in_row = &imgIn[i][0];
        DATA_TYPE *y2_row = &y2[i][0];

        yp1 = SCALAR_VAL(0.0);
        yp2 = SCALAR_VAL(0.0);
        xp1 = SCALAR_VAL(0.0);
        xp2 = SCALAR_VAL(0.0);

        for (j = _PB_H - 1; j >= 0; j--) {
            const DATA_TYPE yv = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;
            y2_row[j] = yv;
            xp2 = xp1;
            xp1 = in_row[j];
            yp2 = yp1;
            yp1 = yv;
        }
    }

    for (i = 0; i < _PB_W; i++) {
        DATA_TYPE *out_row = &imgOut[i][0];
        DATA_TYPE *y1_row = &y1[i][0];
        DATA_TYPE *y2_row = &y2[i][0];
        for (j = 0; j < _PB_H; j++) {
            out_row[j] = c1 * (y1_row[j] + y2_row[j]);
        }
    }

    for (j = 0; j < _PB_H; j++) {
        tm1 = SCALAR_VAL(0.0);
        ym1 = SCALAR_VAL(0.0);
        ym2 = SCALAR_VAL(0.0);
        for (i = 0; i < _PB_W; i++) {
            const DATA_TYPE x0 = imgOut[i][j];
            const DATA_TYPE yv = a5 * x0 + a6 * tm1 + b1 * ym1 + b2 * ym2;
            y1[i][j] = yv;
            tm1 = x0;
            ym2 = ym1;
            ym1 = yv;
        }
    }

    for (j = 0; j < _PB_H; j++) {
        tp1 = SCALAR_VAL(0.0);
        tp2 = SCALAR_VAL(0.0);
        yp1 = SCALAR_VAL(0.0);
        yp2 = SCALAR_VAL(0.0);
        for (i = _PB_W - 1; i >= 0; i--) {
            const DATA_TYPE yv = a7 * tp1 + a8 * tp2 + b1 * yp1 + b2 * yp2;
            y2[i][j] = yv;
            tp2 = tp1;
            tp1 = imgOut[i][j];
            yp2 = yp1;
            yp1 = yv;
        }
    }

    for (i = 0; i < _PB_W; i++) {
        DATA_TYPE *out_row = &imgOut[i][0];
        DATA_TYPE *y1_row = &y1[i][0];
        DATA_TYPE *y2_row = &y2[i][0];
        for (j = 0; j < _PB_H; j++) {
            out_row[j] = c2 * (y1_row[j] + y2_row[j]);
        }
    }

#pragma endscop
}

void kernel_doitgen(int nr, int nq, int np,
                    DATA_TYPE POLYBENCH_3D(A,NR,NQ,NP,nr,nq,np),
                    DATA_TYPE POLYBENCH_2D(C4,NP,NP,np,np),
                    DATA_TYPE POLYBENCH_1D(sum,NP,np))
{
  int r, q, p, s;

#pragma scop
  for (r = 0; r < _PB_NR; r++) {
    for (q = 0; q < _PB_NQ; q++) {
      DATA_TYPE *a_rq = &A[r][q][0];

      for (p = 0; p < _PB_NP; p++)
        sum[p] = SCALAR_VAL(0.0);

      for (s = 0; s < _PB_NP; s++) {
        DATA_TYPE a_s = a_rq[s];
        DATA_TYPE *c4_sp = &C4[s][0];

#if defined(__GNUC__) || defined(__clang__)
        __builtin_assume_aligned(c4_sp, sizeof(DATA_TYPE));
        __builtin_assume_aligned(sum, sizeof(DATA_TYPE));
#endif

        for (p = 0; p + 3 < _PB_NP; p += 4) {
          sum[p]     += a_s * c4_sp[p];
          sum[p + 1] += a_s * c4_sp[p + 1];
          sum[p + 2] += a_s * c4_sp[p + 2];
          sum[p + 3] += a_s * c4_sp[p + 3];
        }
        for (; p < _PB_NP; p++)
          sum[p] += a_s * c4_sp[p];
      }

      for (p = 0; p < _PB_NP; p++)
        a_rq[p] = sum[p];
    }
  }
#pragma endscop
}

static
void kernel_durbin(int n,
		   DATA_TYPE POLYBENCH_1D(r,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n))
{
  DATA_TYPE z[N];
  DATA_TYPE alpha;
  DATA_TYPE beta;
  DATA_TYPE sum;

  int i, k;

#pragma scop
  y[0] = -r[0];
  beta = SCALAR_VAL(1.0);
  alpha = -r[0];

  for (k = 1; k < _PB_N; k++) {
    beta = (SCALAR_VAL(1.0) - alpha * alpha) * beta;
    sum = SCALAR_VAL(0.0);

#if defined(__riscv_vector)
#if defined(DATA_TYPE_IS_DOUBLE)
    {
      int rem = k;
      const DATA_TYPE *pr = &r[k - 1];
      const DATA_TYPE *py = &y[0];
      while (rem > 0) {
        size_t vl = __riscv_vsetvl_e64m1((size_t)rem);
        vfloat64m1_t vy = __riscv_vle64_v_f64m1(py, vl);
        vfloat64m1_t vr = __riscv_vle64_v_f64m1(pr - (ptrdiff_t)vl + 1, vl);
        vbool64_t mask = __riscv_vmsne_vx_u64m1_b64(__riscv_vid_v_u64m1(vl), 0, vl);
        vr = __riscv_vslidedown_vx_f64m1(vr, vr, 0, vl);
        {
          size_t t;
          DATA_TYPE tmp_buf[256];
          for (t = 0; t < vl; ++t) tmp_buf[t] = pr[-(ptrdiff_t)t];
          vr = __riscv_vle64_v_f64m1(tmp_buf, vl);
        }
        {
          vfloat64m1_t prod = __riscv_vfmul_vv_f64m1(vr, vy, vl);
          vfloat64m1_t red = __riscv_vfredusum_vs_f64m1_f64m1(
              prod, __riscv_vfmv_s_f_f64m1(SCALAR_VAL(0.0), vl), vl);
          sum += __riscv_vfmv_f_s_f64m1_f64(red);
        }
        pr -= (ptrdiff_t)vl;
        py += vl;
        rem -= (int)vl;
      }
    }
#elif defined(DATA_TYPE_IS_FLOAT)
    {
      int rem = k;
      const DATA_TYPE *pr = &r[k - 1];
