static
void kernel_floyd_warshall(int n,
			   int POLYBENCH_2D(path,N,N,n,n))
{
  int i, j, k;

#pragma scop
  for (k = 0; k < _PB_N; k++) {
    int *row_k = path[k];

    for (i = 0; i < _PB_N; i++) {
      int *row_i = path[i];
      int pik = row_i[k];

#if defined(__riscv_vector)
      int jv = 0;
      while (jv < _PB_N) {
        size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_N - jv));
        vint32m1_t vij  = __riscv_vle32_v_i32m1((const int32_t *)&row_i[jv], vl);
        vint32m1_t vkj  = __riscv_vle32_v_i32m1((const int32_t *)&row_k[jv], vl);
        vint32m1_t vpik = __riscv_vmv_v_x_i32m1((int32_t)pik, vl);
        vint32m1_t vsum = __riscv_vadd_vv_i32m1(vpik, vkj, vl);
        vbool32_t mask  = __riscv_vmslt_vv_i32m1_b32(vsum, vij, vl);
        vint32m1_t vres = __riscv_vmerge_vvm_i32m1(vij, vsum, mask, vl);
        __riscv_vse32_v_i32m1((int32_t *)&row_i[jv], vres, vl);
        jv += (int)vl;
      }
#else
      for (j = 0; j < _PB_N; j++) {
        int alt = pik + row_k[j];
        row_i[j] = row_i[j] < alt ? row_i[j] : alt;
      }
#endif
    }
  }
#pragma endscop
}

static
void kernel_gemm(int ni, int nj, int nk,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		 DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		 DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_NI; i++) {
    DATA_TYPE *c_row = &C[i][0];
    DATA_TYPE *a_row = &A[i][0];

#if defined(__GNUC__) || defined(__clang__)
    __builtin_assume_aligned(c_row, sizeof(DATA_TYPE));
    __builtin_assume_aligned(a_row, sizeof(DATA_TYPE));
#endif

    for (j = 0; j < _PB_NJ; j++) {
      c_row[j] *= beta;
    }

    for (k = 0; k < _PB_NK; k++) {
      DATA_TYPE aalpha = alpha * a_row[k];
      DATA_TYPE *b_row = &B[k][0];

#if defined(__GNUC__) || defined(__clang__)
      __builtin_assume_aligned(b_row, sizeof(DATA_TYPE));
#endif

      for (j = 0; j < _PB_NJ; j++) {
        c_row[j] += aalpha * b_row[j];
      }
    }
  }
#pragma endscop

}

static
void kernel_gemver(int n,
		   DATA_TYPE alpha,
		   DATA_TYPE beta,
		   DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		   DATA_TYPE POLYBENCH_1D(u1,N,n),
		   DATA_TYPE POLYBENCH_1D(v1,N,n),
		   DATA_TYPE POLYBENCH_1D(u2,N,n),
		   DATA_TYPE POLYBENCH_1D(v2,N,n),
		   DATA_TYPE POLYBENCH_1D(w,N,n),
		   DATA_TYPE POLYBENCH_1D(x,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n),
		   DATA_TYPE POLYBENCH_1D(z,N,n))
{
  int i, j;

#pragma scop

#if defined(__riscv_vector) && (defined(DATA_TYPE_IS_FLOAT) || defined(DATA_TYPE_IS_DOUBLE))

  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE *Ai = A[i];
    DATA_TYPE u1i = u1[i];
    DATA_TYPE u2i = u2[i];
    j = 0;
    while (j < _PB_N) {
      size_t vl;
#if defined(DATA_TYPE_IS_FLOAT)
      vl = __riscv_vsetvl_e32m1((size_t)(_PB_N - j));
      {
        vfloat32m1_t vA  = __riscv_vle32_v_f32m1(&Ai[j], vl);
        vfloat32m1_t vv1 = __riscv_vle32_v_f32m1(&v1[j], vl);
        vfloat32m1_t vv2 = __riscv_vle32_v_f32m1(&v2[j], vl);
        vA = __riscv_vfmacc_vf_f32m1(vA, u1i, vv1, vl);
        vA = __riscv_vfmacc_vf_f32m1(vA, u2i, vv2, vl);
        __riscv_vse32_v_f32m1(&Ai[j], vA, vl);
      }
#else
      vl = __riscv_vsetvl_e64m1((size_t)(_PB_N - j));
      {
        vfloat64m1_t vA  = __riscv_vle64_v_f64m1(&Ai[j], vl);
        vfloat64m1_t vv1 = __riscv_vle64_v_f64m1(&v1[j], vl);
        vfloat64m1_t vv2 = __riscv_vle64_v_f64m1(&v2[j], vl);
        vA = __riscv_vfmacc_vf_f64m1(vA, u1i, vv1, vl);
        vA = __riscv_vfmacc_vf_f64m1(vA, u2i, vv2, vl);
        __riscv_vse64_v_f64m1(&Ai[j], vA, vl);
      }
#endif
      j += (int)vl;
    }
  }

  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE sum = x[i];
    j = 0;
    while (j < _PB_N) {
      size_t vl;
#if defined(DATA_TYPE_IS_FLOAT)
      vl = __riscv_vsetvl_e32m1((size_t)(_PB_N - j));
      {
        vfloat32m1_t vAcol = __riscv_vlse32_v_f32m1(&A[j][i], (ptrdiff_t)(n * (int)sizeof(DATA_TYPE)), vl);
        vfloat32m1_t vy    = __riscv_vle32_v_f32m1(&y[j], vl);
        vfloat32m1_t vp    = __riscv_vfmul_vv_f32m1(vAcol, vy, vl);
        vfloat32m1_t vbeta = __riscv_vfmul_vf_f32m1(vp, beta, vl);
        size_t k;
        for (k = 0; k < vl; k++) {
          DATA_TYPE tmp;
          __riscv_vse32_v_f32m1(&tmp, __riscv_vslidedown_vx_f32m1(vbeta, k, vl), 1);
          sum = sum + tmp;
        }
      }
#else
      vl = __riscv_vsetvl_e64m1((size_t)(_PB_N - j));
      {
        vfloat64m1_t vAcol = __riscv_vlse64_v_f64m1(&A[j][i], (ptrdiff_t)(n * (int)sizeof(DATA_TYPE)), vl);
        vfloat64m1_t vy    = __riscv_vle64_v_f64m1(&y[j], vl);
        vfloat64m1_t vp    = __riscv_vfmul_vv_f64m1(vAcol, vy, vl);
        vfloat64m1_t vbeta = __riscv_vfmul_vf_f64m1(vp, beta, vl);
        size_t k;
        for (k = 0; k < vl; k++) {
          DATA_TYPE tmp;
          __riscv_vse64_v_f64m1(&tmp, __riscv_vslidedown_vx_f64m1(vbeta, k, vl), 1);
          sum = sum + tmp;
        }
      }
#endif
      j += (int)vl;
    }
    x[i] = sum;
  }

  for (i = 0; i < _PB_N; i++)
    x[i] = x[i] + z[i];

  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE sum = w[i];
    DATA_TYPE *Ai = A[i];
    j = 0;
    while (j < _PB_N) {
      size_t vl;
#if defined(DATA_TYPE_IS_FLOAT)
      vl = __riscv_vsetvl_e32m1((size_t)(_PB_N - j));
      {
        vfloat32m1_t vA = __riscv_vle32_v_f32m1(&Ai[j], vl);
        vfloat32m1_t vx = __riscv_vle32_v_f32m1(&x[j], vl);
        vfloat32m1_t vp = __riscv_vfmul_vv_f32m1(vA, vx, vl);
        vfloat32m1_t va = __riscv_vfmul_vf_f32m1(vp, alpha, vl);
        size_t k;
        for (k = 0; k < vl; k++) {
          DATA_TYPE tmp;
          __riscv_vse32_v_f32m1(&tmp, __riscv_vslidedown_vx_f32m1(va, k, vl), 1);
          sum = sum + tmp;
        }
      }
#else
      vl = __riscv_vsetvl_e64m1((size_t)(_PB_N - j));
      {
        vfloat64m1_t vA = __riscv_vle64_v_f64m1(&Ai[j], vl);
        vfloat64m1_t vx = __riscv_vle64_v_f64m1(&x[j], vl);
        vfloat64m1_t vp = __riscv_vfmul_vv_f64m1(vA, vx, vl);
        vfloat64m1_t va = __riscv_vfmul_vf_f64m1(vp, alpha, vl);
        size_t k;
        for (k = 0; k < vl; k++) {
          DATA_TYPE tmp;
          __riscv_vse64_v_f64m1(&tmp, __riscv_vslidedown_vx_f64m1(va, k, vl), 1);
          sum = sum + tmp;
        }
      }
#endif
      j += (int)vl;
    }
    w[i] = sum;
  }

#else

  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_N; j++)
      A[i][j] = A[i][j] + u1[i] * v1[j] + u2[i] * v2[j];

  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_N; j++)
      x[i] = x[i] + beta * A[j][i] * y[j];

  for (i = 0; i < _PB_N; i++)
    x[i] = x[i] + z[i];

  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_N; j++)
      w[i] = w[i] + alpha * A[i][j] * x[j];

#endif

#pragma endscop
}

