static
void kernel_gesummv(int n,
		    DATA_TYPE alpha,
		    DATA_TYPE beta,
		    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		    DATA_TYPE POLYBENCH_2D(B,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(tmp,N,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j;

#pragma scop
  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE sum_tmp = SCALAR_VAL(0.0);
      DATA_TYPE sum_y = SCALAR_VAL(0.0);
      DATA_TYPE *a_row = A[i];
      DATA_TYPE *b_row = B[i];

#if defined(__riscv_vector) && defined(DATA_TYPE_IS_FLOAT)
      {
        size_t avl = (size_t)_PB_N;
        int idx = 0;
        vfloat32m1_t vacc_tmp = __riscv_vfmv_v_f_f32m1(0.0f, 1);
        vfloat32m1_t vacc_y = __riscv_vfmv_v_f_f32m1(0.0f, 1);

        while (avl > 0)
          {
            size_t vl = __riscv_vsetvl_e32m1(avl);
            vfloat32m1_t va = __riscv_vle32_v_f32m1(&a_row[idx], vl);
            vfloat32m1_t vb = __riscv_vle32_v_f32m1(&b_row[idx], vl);
            vfloat32m1_t vx = __riscv_vle32_v_f32m1(&x[idx], vl);

            vacc_tmp = __riscv_vfmacc_vv_f32m1(vacc_tmp, va, vx, vl);
            vacc_y = __riscv_vfmacc_vv_f32m1(vacc_y, vb, vx, vl);

            idx += (int)vl;
            avl -= vl;
          }

        {
          size_t vlmax = __riscv_vsetvl_e32m1(_PB_N > 0 ? (size_t)_PB_N : 1);
          size_t vl1 = __riscv_vsetvl_e32m1(1);
          vfloat32m1_t vzero = __riscv_vfmv_v_f_f32m1(0.0f, vl1);
          vfloat32m1_t vred_tmp = __riscv_vfredusum_vs_f32m1_f32m1(vacc_tmp, vzero, vlmax);
          vfloat32m1_t vred_y = __riscv_vfredusum_vs_f32m1_f32m1(vacc_y, vzero, vlmax);
          sum_tmp = (DATA_TYPE)__riscv_vfmv_f_s_f32m1_f32(vred_tmp);
          sum_y = (DATA_TYPE)__riscv_vfmv_f_s_f32m1_f32(vred_y);
        }
      }
#elif defined(__riscv_vector) && defined(DATA_TYPE_IS_DOUBLE)
      {
        size_t avl = (size_t)_PB_N;
        int idx = 0;
        vfloat64m1_t vacc_tmp = __riscv_vfmv_v_f_f64m1(0.0, 1);
        vfloat64m1_t vacc_y = __riscv_vfmv_v_f_f64m1(0.0, 1);

        while (avl > 0)
          {
            size_t vl = __riscv_vsetvl_e64m1(avl);
            vfloat64m1_t va = __riscv_vle64_v_f64m1(&a_row[idx], vl);
            vfloat64m1_t vb = __riscv_vle64_v_f64m1(&b_row[idx], vl);
            vfloat64m1_t vx = __riscv_vle64_v_f64m1(&x[idx], vl);

            vacc_tmp = __riscv_vfmacc_vv_f64m1(vacc_tmp, va, vx, vl);
            vacc_y = __riscv_vfmacc_vv_f64m1(vacc_y, vb, vx, vl);

            idx += (int)vl;
            avl -= vl;
          }

        {
          size_t vlmax = __riscv_vsetvl_e64m1(_PB_N > 0 ? (size_t)_PB_N : 1);
          size_t vl1 = __riscv_vsetvl_e64m1(1);
          vfloat64m1_t vzero = __riscv_vfmv_v_f_f64m1(0.0, vl1);
          vfloat64m1_t vred_tmp = __riscv_vfredusum_vs_f64m1_f64m1(vacc_tmp, vzero, vlmax);
          vfloat64m1_t vred_y = __riscv_vfredusum_vs_f64m1_f64m1(vacc_y, vzero, vlmax);
          sum_tmp = (DATA_TYPE)__riscv_vfmv_f_s_f64m1_f64(vred_tmp);
          sum_y = (DATA_TYPE)__riscv_vfmv_f_s_f64m1_f64(vred_y);
        }
      }
#else
      for (j = 0; j < _PB_N; j++)
	{
	  sum_tmp = a_row[j] * x[j] + sum_tmp;
	  sum_y = b_row[j] * x[j] + sum_y;
	}
#endif

      tmp[i] = sum_tmp;
      y[i] = alpha * sum_tmp + beta * sum_y;
    }
#pragma endscop

}

static
void kernel_gramschmidt(int m, int n,
                        DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
                        DATA_TYPE POLYBENCH_2D(R,N,N,n,n),
                        DATA_TYPE POLYBENCH_2D(Q,M,N,m,n))
{
  int i, j, k;
  DATA_TYPE nrm;

#pragma scop
  for (k = 0; k < _PB_N; k++) {
    nrm = SCALAR_VAL(0.0);
    for (i = 0; i < _PB_M; i++)
      nrm += A[i][k] * A[i][k];

    R[k][k] = SQRT_FUN(nrm);

    for (i = 0; i < _PB_M; i++)
      Q[i][k] = A[i][k] / R[k][k];

    for (j = k + 1; j < _PB_N; j++) {
      DATA_TYPE rkj = SCALAR_VAL(0.0);

      for (i = 0; i < _PB_M; i++)
        rkj += Q[i][k] * A[i][j];

      R[k][j] = rkj;

      for (i = 0; i < _PB_M; i++)
        A[i][j] = A[i][j] - Q[i][k] * rkj;
    }
  }
#pragma endscop

}

static
void kernel_heat_3d(int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n),
		      DATA_TYPE POLYBENCH_3D(B,N,N,N,n,n,n))
{
  int t, i, j, k;

#pragma scop
  {
    const int Nn = _PB_N;

    for (t = 1; t <= TSTEPS; t++) {
      for (i = 1; i < Nn - 1; i++) {
        for (j = 1; j < Nn - 1; j++) {
          DATA_TYPE *b_row = &B[i][j][0];
          DATA_TYPE *a_c   = &A[i][j][0];
          DATA_TYPE *a_im1 = &A[i - 1][j][0];
          DATA_TYPE *a_ip1 = &A[i + 1][j][0];
          DATA_TYPE *a_jm1 = &A[i][j - 1][0];
          DATA_TYPE *a_jp1 = &A[i][j + 1][0];

          for (k = 1; k < Nn - 1; k++) {
            DATA_TYPE center = a_c[k];
            b_row[k] = SCALAR_VAL(0.125) * (a_ip1[k] - SCALAR_VAL(2.0) * center + a_im1[k])
                     + SCALAR_VAL(0.125) * (a_jp1[k] - SCALAR_VAL(2.0) * center + a_jm1[k])
                     + SCALAR_VAL(0.125) * (a_c[k + 1] - SCALAR_VAL(2.0) * center + a_c[k - 1])
                     + center;
          }
        }
      }

      for (i = 1; i < Nn - 1; i++) {
        for (j = 1; j < Nn - 1; j++) {
          DATA_TYPE *a_row = &A[i][j][0];
          DATA_TYPE *b_c   = &B[i][j][0];
          DATA_TYPE *b_im1 = &B[i - 1][j][0];
          DATA_TYPE *b_ip1 = &B[i + 1][j][0];
          DATA_TYPE *b_jm1 = &B[i][j - 1][0];
          DATA_TYPE *b_jp1 = &B[i][j + 1][0];

          for (k = 1; k < Nn - 1; k++) {
            DATA_TYPE center = b_c[k];
            a_row[k] = SCALAR_VAL(0.125) * (b_ip1[k] - SCALAR_VAL(2.0) * center + b_im1[k])
                     + SCALAR_VAL(0.125) * (b_jp1[k] - SCALAR_VAL(2.0) * center + b_jm1[k])
                     + SCALAR_VAL(0.125) * (b_c[k + 1] - SCALAR_VAL(2.0) * center + b_c[k - 1])
                     + center;
          }
        }
      }
    }
  }
#pragma endscop

}

static
void kernel_jacobi_1d(int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_1D(A,N,n),
			    DATA_TYPE POLYBENCH_1D(B,N,n))
{
  int t, i;

#pragma scop
  for (t = 0; t < _PB_TSTEPS; t++)
    {
#if defined(__riscv_vector) && defined(DATA_TYPE_IS_DOUBLE)
      {
        const DATA_TYPE c = (DATA_TYPE)0.33333;
        const int limit = _PB_N - 1;

        i = 1;
        while (i < limit) {
          size_t vl = __riscv_vsetvl_e64m1((size_t)(limit - i));
          vfloat64m1_t va_l = __riscv_vle64_v_f64m1(&A[i - 1], vl);
          vfloat64m1_t va_c = __riscv_vle64_v_f64m1(&A[i], vl);
          vfloat64m1_t va_r = __riscv_vle64_v_f64m1(&A[i + 1], vl);
          vfloat64m1_t vs = __riscv_vfadd_vv_f64m1(va_l, va_c, vl);
          vs = __riscv_vfadd_vv_f64m1(vs, va_r, vl);
          vs = __riscv_vfmul_vf_f64m1(vs, c, vl);
          __riscv_vse64_v_f64m1(&B[i], vs, vl);
          i += (int)vl;
        }

        i = 1;
        while (i < limit) {
          size_t vl = __riscv_vsetvl_e64m1((size_t)(limit - i));
          vfloat64m1_t vb_l = __riscv_vle64_v_f64m1(&B[i - 1], vl);
          vfloat64m1_t vb_c = __riscv_vle64_v_f64m1(&B[i], vl);
          vfloat64m1_t vb_r = __riscv_vle64_v_f64m1(&B[i + 1], vl);
          vfloat64m1_t vs = __riscv_vfadd_vv_f64m1(vb_l, vb_c, vl);
          vs = __riscv_vfadd_vv_f64m1(vs, vb_r, vl);
          vs = __riscv_vfmul_vf_f64m1(vs, c, vl);
          __riscv_vse64_v_f64m1(&A[i], vs, vl);
          i += (int)vl;
        }
      }
#elif defined(__riscv_vector) && defined(DATA_TYPE_IS_FLOAT)
      {
        const DATA_TYPE c = (DATA_TYPE)0.33333f;
        const int limit = _PB_N - 1;

        i = 1;
        while (i < limit) {
          size_t vl = __riscv_vsetvl_e32m1((size_t)(limit - i));
          vfloat32m1_t va_l = __riscv_vle32_v_f32m1(&A[i - 1], vl);
          vfloat32m1_t va_c = __riscv_vle32_v_f32m1(&A[i], vl);
          vfloat32m1_t va_r = __riscv_vle32_v_f32m1(&A[i + 1], vl);
          vfloat32m1_t vs = __riscv_vfadd_vv_f32m1(va_l, va_c, vl);
          vs = __riscv_vfadd_vv_f32m1(vs, va_r, vl);
          vs = __riscv_vfmul_vf_f32m1(vs, c, vl);
          __riscv_vse32_v_f32m1(&B[i], vs, vl);
          i += (int)vl;
        }

        i = 1;
        while (i < limit) {
          size_t vl = __riscv_vsetvl_e32m1((size_t)(limit - i));
          vfloat32m1_t vb_l = __riscv_vle32_v_f32m1(&B[i - 1], vl);
          vfloat32m1_t vb_c = __riscv_vle32_v_f32m1(&B[i], vl);
          vfloat32m1_t vb_r = __riscv_vle32_v_f32m1(&B[i + 1], vl);
          vfloat32m1_t vs = __riscv_vfadd_vv_f32m1(vb_l, vb_c, vl);
          vs = __riscv_vfadd_vv_f32m1(vs, vb_r, vl);
          vs = __riscv_vfmul_vf_f32m1(vs, c, vl);
          __riscv_vse32_v_f32m1(&A[i], vs, vl);
          i += (int)vl;
        }
      }
#else
      for (i = 1; i < _PB_N - 1; i++)
	B[i] = 0.33333 * (A[i-1] + A[i] + A[i + 1]);
      for (i = 1; i < _PB_N - 1; i++)
	A[i] = 0.33333 * (B[i-1] + B[i] + B[i + 1]);
#endif
    }
#pragma endscop

}

static
void kernel_jacobi_2d(int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
			    DATA_TYPE POLYBENCH_2D(B,N,N,n,n))
{
  int t, i, j;

#pragma scop
  for (t = 0; t < _PB_TSTEPS; t++)
  {
    for (i = 1; i < _PB_N - 1; i++)
    {
      DATA_TYPE *Ai   = &A[i][0];
      DATA_TYPE *Aim1 = &A[i - 1][0];
      DATA_TYPE *Aip1 = &A[i + 1][0];
      DATA_TYPE *Bi   = &B[i][0];

      for (j = 1; j < _PB_N - 1; j++)
        Bi[j] = SCALAR_VAL(0.2) * (Ai[j] + Ai[j-1] + Ai[j+1] + Aip1[j] + Aim1[j]);
    }

    for (i = 1; i < _PB_N - 1; i++)
    {
      DATA_TYPE *Bi   = &B[i][0];
      DATA_TYPE *Bim1 = &B[i - 1][0];
      DATA_TYPE *Bip1 = &B[i + 1][0];
      DATA_TYPE *Ai   = &A[i][0];

      for (j = 1; j < _PB_N - 1; j++)
        Ai[j] = SCALAR_VAL(0.2) * (Bi[j] + Bi[j-1] + Bi[j+1] + Bip1[j] + Bim1[j]);
    }
  }
#pragma endscop

}

static
void kernel_lu(int n,
	       DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE *Ai = A[i];

    for (j = 0; j < i; j++) {
      DATA_TYPE sum = Ai[j];

      for (k = 0; k < j; k++) {
        sum -= Ai[k] * A[k][j];
      }

      Ai[j] = sum / A[j][j];
    }

    for (j = i; j < _PB_N; j++) {
      DATA_TYPE sum = Ai[j];

      for (k = 0; k < i; k++) {
        sum -= Ai[k] * A[k][j];
      }

      Ai[j] = sum;
    }
  }
#pragma endscop
}

