        vfloat64m1_t vred = __riscv_vfredusum_vs_f64m1_f64m1(vzero, vacc, vzero, 1);
        w -= (DATA_TYPE)__riscv_vfmv_f_s_f64m1_f64(vred);
      }
    }
#else
    for (j = 0; j < i; j++)
      w -= Ai[j] * y[j];
#endif
#else
    for (j = 0; j < i; j++)
      w -= Ai[j] * y[j];
#endif

    y[i] = w;
  }

  for (i = _PB_N - 1; i >= 0; i--) {
    DATA_TYPE *Ai = &A[i][0];
    w = y[i];

#if defined(__riscv_vector) && defined(__riscv_v_intrinsic)
#if defined(DATA_TYPE_IS_FLOAT)
    {
      size_t off = (size_t)(i + 1);
      size_t rem = (size_t)_PB_N - off;
      vfloat32m1_t vacc = __riscv_vfmv_v_f_f32m1(0.0f, 1);
      while (rem > 0) {
