        vfloat32m1_t vred = __riscv_vfredusum_vs_f32m1_f32m1(vzero, vacc, vzero, 1);
        w -= (DATA_TYPE)__riscv_vfmv_f_s_f32m1_f32(vred);
      }
    }
#elif defined(DATA_TYPE_IS_DOUBLE)
    {
      size_t off = (size_t)(i + 1);
      size_t rem = (size_t)_PB_N - off;
      vfloat64m1_t vacc = __riscv_vfmv_v_f_f64m1(0.0, 1);
      while (rem > 0) {
        size_t vl = __riscv_vsetvl_e64m1(rem);
        vfloat64m1_t va = __riscv_vle64_v_f64m1((const double *)(Ai + off), vl);
        vfloat64m1_t vxv = __riscv_vle64_v_f64m1((const double *)(x + off), vl);
        vacc = __riscv_vfmacc_vv_f64m1(vacc, va, vxv, vl);
        off += vl;
        rem -= vl;
      }
      {
