#else
    for (j = i + 1; j < _PB_N; j++)
      w -= Ai[j] * x[j];
#endif
#else
    for (j = i + 1; j < _PB_N; j++)
      w -= Ai[j] * x[j];
#endif

    x[i] = w / Ai[i];
  }
#pragma endscop
}

static
void kernel_mvt(int n,
