        vfloat32m1_t vred = __riscv_vfredusum_vs_f32m1_f32m1(vacc, vzero, vlmax);
        sum += __riscv_vfmv_f_s_f32m1_f32(vred);
      }
    }
#endif
    x1[i] = sum;
  }

  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE sum = x2[i];
    j = 0;

#if defined(DATA_TYPE_IS_DOUBLE)
    {
      size_t vl;
      size_t vlmax = __riscv_vsetvlmax_e64m1();
      vfloat64m1_t vacc = __riscv_vfmv_v_f_f64m1(0.0, vlmax);
      while (j < _PB_N) {
        vl = __riscv_vsetvl_e64m1((size_t)(_PB_N - j));
        vfloat64m1_t vy = __riscv_vle64_v_f64m1((const double *)(y_2 + j), vl);
        vuint64m1_t vidx = __riscv_vid_v_u64m1(vl);
        vidx = __riscv_vmul_vx_u64m1(vidx, (uint64_t)(N * (int)sizeof(DATA_TYPE)), vl);
        vfloat64m1_t va = __riscv_vluxei64_v_f64m1((const double *)&A[j][i], vidx, vl);
        vacc = __riscv_vfmacc_vv_f64m1(vacc, va, vy, vl);
