      while (j < _PB_N) {
        vl = __riscv_vsetvl_e32m1((size_t)(_PB_N - j));
        vfloat32m1_t vy = __riscv_vle32_v_f32m1((const float *)(y_2 + j), vl);
        vuint32m1_t vidx = __riscv_vid_v_u32m1(vl);
        vidx = __riscv_vmul_vx_u32m1(vidx, (uint32_t)(N * (int)sizeof(DATA_TYPE)), vl);
        vfloat32m1_t va = __riscv_vluxei32_v_f32m1((const float *)&A[j][i], vidx, vl);
        vacc = __riscv_vfmacc_vv_f32m1(vacc, va, vy, vl);
        j += (int)vl;
      }
      {
        size_t vl1 = __riscv_vsetvl_e32m1(1);
        vfloat32m1_t vzero = __riscv_vfmv_v_f_f32m1(0.0f, vl1);
        vfloat32m1_t vred = __riscv_vfredusum_vs_f32m1_f32m1(vacc, vzero, vlmax);
        sum += __riscv_vfmv_f_s_f32m1_f32(vred);
      }
    }
#endif
    x2[i] = sum;
  }
#else
  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_N; j++)
      x1[i] = x1[i] + A[i][j] * y_1[j];

  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_N; j++)
      x2[i] = x2[i] + A[j][i] * y_2[j];
#endif
#else
  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_N; j++)
      x1[i] = x1[i] + A[i][j] * y_1[j];

  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_N; j++)
      x2[i] = x2[i] + A[j][i] * y_2[j];
#endif
#else
  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_N; j++)
      x1[i] = x1[i] + A[i][j] * y_1[j];

  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_N; j++)
      x2[i] = x2[i] + A[j][i] * y_2[j];
#endif
#pragma endscop

}

static
void kernel_nussinov(int n, base POLYBENCH_1D(seq,N,n),
			   DATA_TYPE POLYBENCH_2D(table,N,N,n,n))
{
  int i, j, k;

#pragma scop
  for (i = _PB_N - 1; i >= 0; --i) {
    DATA_TYPE *table_i = table[i];
    DATA_TYPE *table_ip1 = table[i + 1];
    base seq_i = seq[i];

    for (j = i + 1; j < _PB_N; ++j) {
      DATA_TYPE best = table_i[j];

      {
        DATA_TYPE v = table_i[j - 1];
        if (v > best) best = v;
      }

      {
        DATA_TYPE v = table_ip1[j];
        if (v > best) best = v;
      }

      {
        DATA_TYPE v = table_ip1[j - 1];
        if (i < j - 1)
          v = v + match(seq_i, seq[j]);
        if (v > best) best = v;
      }

      for (k = i + 1; k < j; ++k) {
        DATA_TYPE v = table_i[k] + table[k + 1][j];
        if (v > best) best = v;
      }

      table_i[j] = best;
    }
  }
#pragma endscop

}

static
void kernel_seidel_2d(int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int t, i, j;

#pragma scop
  for (t = 0; t <= _PB_TSTEPS - 1; t++) {
    for (i = 1; i <= _PB_N - 2; i++) {
      DATA_TYPE *rowm1 = &A[i - 1][0];
      DATA_TYPE *row0  = &A[i][0];
      DATA_TYPE *rowp1 = &A[i + 1][0];

      for (j = 1; j <= _PB_N - 2; j++) {
        row0[j] = (rowm1[j-1] + rowm1[j] + rowm1[j+1]
                 + row0[j-1] + row0[j] + row0[j+1]
                 + rowp1[j-1] + rowp1[j] + rowp1[j+1]) / SCALAR_VAL(9.0);
      }
    }
  }
#pragma endscop

}

