static
void kernel_symm(int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,M,N,m,n),
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;
  DATA_TYPE temp2;

#pragma scop
#if defined(__riscv_vector) && defined(DATA_TYPE_IS_FLOAT)
  for (i = 0; i < _PB_M; i++) {
    DATA_TYPE *Ai = &A[i][0];
    DATA_TYPE Aii = A[i][i];

    for (j = 0; j < _PB_N; j++) {
      DATA_TYPE Bij = B[i][j];
      DATA_TYPE aBij = alpha * Bij;
      const ptrdiff_t stride = (ptrdiff_t)n * (ptrdiff_t)sizeof(DATA_TYPE);
      temp2 = 0;
      k = 0;

      vfloat32m1_t vacc = __riscv_vfmv_v_f_f32m1(0.0f, 1);
      while (k < i) {
        size_t vl = __riscv_vsetvl_e32m1((size_t)(i - k));
        vfloat32m1_t vA = __riscv_vle32_v_f32m1(&Ai[k], vl);
        vfloat32m1_t vB = __riscv_vlse32_v_f32m1(&B[k][j], stride, vl);
        vfloat32m1_t vC = __riscv_vlse32_v_f32m1(&C[k][j], stride, vl);

        vacc = __riscv_vfmacc_vv_f32m1(vacc, vB, vA, vl);
        vC = __riscv_vfmacc_vf_f32m1(vC, aBij, vA, vl);
        __riscv_vsse32_v_f32m1(&C[k][j], stride, vC, vl);

        k += (int)vl;
      }

      {
        vfloat32m1_t vzero = __riscv_vfmv_v_f_f32m1(0.0f, 1);
        vfloat32m1_t vred = __riscv_vfredusum_vs_f32m1_f32m1(vzero, vacc, vzero, 1);
        temp2 = __riscv_vfmv_f_s_f32m1_f32(vred);
      }

      C[i][j] = beta * C[i][j] + aBij * Aii + alpha * temp2;
    }
  }
#elif defined(__riscv_vector) && defined(DATA_TYPE_IS_DOUBLE)
  for (i = 0; i < _PB_M; i++) {
    DATA_TYPE *Ai = &A[i][0];
    DATA_TYPE Aii = A[i][i];

    for (j = 0; j < _PB_N; j++) {
      DATA_TYPE Bij = B[i][j];
      DATA_TYPE aBij = alpha * Bij;
      const ptrdiff_t stride = (ptrdiff_t)n * (ptrdiff_t)sizeof(DATA_TYPE);
      temp2 = 0;
      k = 0;

      vfloat64m1_t vacc = __riscv_vfmv_v_f_f64m1(0.0, 1);
      while (k < i) {
        size_t vl = __riscv_vsetvl_e64m1((size_t)(i - k));
        vfloat64m1_t vA = __riscv_vle64_v_f64m1(&Ai[k], vl);
        vfloat64m1_t vB = __riscv_vlse64_v_f64m1(&B[k][j], stride, vl);
        vfloat64m1_t vC = __riscv_vlse64_v_f64m1(&C[k][j], stride, vl);

        vacc = __riscv_vfmacc_vv_f64m1(vacc, vB, vA, vl);
        vC = __riscv_vfmacc_vf_f64m1(vC, aBij, vA, vl);
        __riscv_vsse64_v_f64m1(&C[k][j], stride, vC, vl);

        k += (int)vl;
      }

      {
        vfloat64m1_t vzero = __riscv_vfmv_v_f_f64m1(0.0, 1);
        vfloat64m1_t vred = __riscv_vfredusum_vs_f64m1_f64m1(vzero, vacc, vzero, 1);
        temp2 = __riscv_vfmv_f_s_f64m1_f64(vred);
      }

      C[i][j] = beta * C[i][j] + aBij * Aii + alpha * temp2;
    }
  }
#else
  for (i = 0; i < _PB_M; i++)
    for (j = 0; j < _PB_N; j++)
    {
      DATA_TYPE *Ai = &A[i][0];
      DATA_TYPE Bij = B[i][j];
      DATA_TYPE aBij = alpha * Bij;
      temp2 = 0;
      for (k = 0; k < i; k++) {
        C[k][j] += aBij * Ai[k];
        temp2 += B[k][j] * Ai[k];
      }
      C[i][j] = beta * C[i][j] + aBij * A[i][i] + alpha * temp2;
    }
#endif
#pragma endscop

}

static
void kernel_syr2k(int n, int m,
		  double alpha,
		  double beta,
		  double POLYBENCH_2D(C,N,N,n,n),
		  double POLYBENCH_2D(A,N,M,n,m),
		  double POLYBENCH_2D(B,N,M,n,m))
{
  int i, j, k;

#pragma scop
#if defined(__riscv_vector)
  for (i = 0; i < _PB_N; i++) {
    double *Ci = C[i];
    double *Ai = A[i];

    j = 0;
    while (j <= i) {
      size_t vl = __riscv_vsetvl_e64m1((size_t)(i + 1 - j));
      vfloat64m1_t vc = __riscv_vle64_v_f64m1(&Ci[j], vl);
      vc = __riscv_vfmul_vf_f64m1(vc, beta, vl);
      __riscv_vse64_v_f64m1(&Ci[j], vc, vl);
      j += (int)vl;
    }

    for (k = 0; k < _PB_M; k++) {
      double aik_alpha = alpha * Ai[k];
      double bik_alpha = alpha * B[i][k];

      j = 0;
      while (j <= i) {
        size_t vl = __riscv_vsetvl_e64m1((size_t)(i + 1 - j));
        vfloat64m1_t vc  = __riscv_vle64_v_f64m1(&Ci[j], vl);
        vfloat64m1_t vaj = __riscv_vlse64_v_f64m1(&A[j][k], (ptrdiff_t)(m * (int)sizeof(double)), vl);
        vfloat64m1_t vbj = __riscv_vlse64_v_f64m1(&B[j][k], (ptrdiff_t)(m * (int)sizeof(double)), vl);
        vc = __riscv_vfmacc_vf_f64m1(vc, bik_alpha, vaj, vl);
        vc = __riscv_vfmacc_vf_f64m1(vc, aik_alpha, vbj, vl);
        __riscv_vse64_v_f64m1(&Ci[j], vc, vl);
        j += (int)vl;
      }
    }
  }
#else
  for (i = 0; i < _PB_N; i++) {
    for (j = 0; j <= i; j++)
      C[i][j] *= beta;
    for (k = 0; k < _PB_M; k++) {
      double aik_alpha = alpha * A[i][k];
      double bik_alpha = alpha * B[i][k];
      for (j = 0; j <= i; j++) {
	C[i][j] += A[j][k] * bik_alpha + B[j][k] * aik_alpha;
      }
    }
  }
#endif
#pragma endscop

}

static
void kernel_syrk(int n, int m,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE *Ci = &C[i][0];
    DATA_TYPE *Ai = &A[i][0];

    for (j = 0; j <= i; j++)
      Ci[j] *= beta;

    for (k = 0; k < _PB_M; k++) {
      DATA_TYPE aik_alpha = alpha * Ai[k];
      for (j = 0; j <= i; j++)
        Ci[j] += aik_alpha * A[j][k];
    }
  }
#pragma endscop

}

static
void kernel_trisolv(int n,
		    DATA_TYPE POLYBENCH_2D(L,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(b,N,n))
{
  int i, j;

#pragma scop
  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE xi = b[i];
      DATA_TYPE *Li = L[i];

#if defined(__riscv_vector)
#if defined(DATA_TYPE_IS_DOUBLE)
      j = 0;
      {
        size_t rem = (size_t)i;
        while (rem > 0)
          {
            size_t vl = __riscv_vsetvl_e64m1(rem);
            vfloat64m1_t vL = __riscv_vle64_v_f64m1((const double *)(Li + j), vl);
            vfloat64m1_t vx = __riscv_vle64_v_f64m1((const double *)(x + j), vl);
            vfloat64m1_t vacc = __riscv_vfmul_vv_f64m1(vL, vx, vl);
            vfloat64m1_t vzero = __riscv_vfmv_v_f_f64m1(0.0, 1);
            vfloat64m1_t vsum = __riscv_vfredusum_vs_f64m1_f64m1(vacc, vzero, vl);
            xi -= (DATA_TYPE)__riscv_vfmv_f_s_f64m1_f64(vsum);
            j += (int)vl;
            rem -= vl;
          }
      }
#elif defined(DATA_TYPE_IS_FLOAT)
      j = 0;
      {
        size_t rem = (size_t)i;
        while (rem > 0)
          {
            size_t vl = __riscv_vsetvl_e32m1(rem);
            vfloat32m1_t vL = __riscv_vle32_v_f32m1((const float *)(Li + j), vl);
            vfloat32m1_t vx = __riscv_vle32_v_f32m1((const float *)(x + j), vl);
            vfloat32m1_t vacc = __riscv_vfmul_vv_f32m1(vL, vx, vl);
            vfloat32m1_t vzero = __riscv_vfmv_v_f_f32m1(0.0f, 1);
            vfloat32m1_t vsum = __riscv_vfredusum_vs_f32m1_f32m1(vacc, vzero, vl);
            xi -= (DATA_TYPE)__riscv_vfmv_f_s_f32m1_f32(vsum);
            j += (int)vl;
            rem -= vl;
          }
      }
#else
      for (j = 0; j < i; j++)
        xi -= Li[j] * x[j];
#endif
#else
      for (j = 0; j < i; j++)
        xi -= Li[j] * x[j];
#endif

      x[i] = xi / Li[i];
    }
#pragma endscop
}

static
void kernel_trmm(int m, int n,
		 double alpha,
		 double A[m][m],
		 double B[m][n])
{
  int i, j, k;

#pragma scop
#if defined(__riscv_vector)
  for (i = 0; i < m; i++) {
    double *Bi = B[i];
    for (j = 0; j < n; ) {
      size_t vl = __riscv_vsetvl_e64m1((size_t)(n - j));
      vfloat64m1_t acc = __riscv_vle64_v_f64m1(&Bi[j], vl);

      for (k = i + 1; k < m; k++) {
        double aik = A[k][i];
        vfloat64m1_t bk = __riscv_vle64_v_f64m1(&B[k][j], vl);
        acc = __riscv_vfmacc_vf_f64m1(acc, aik, bk, vl);
      }

      acc = __riscv_vfmul_vf_f64m1(acc, alpha, vl);
      __riscv_vse64_v_f64m1(&Bi[j], acc, vl);
      j += (int)vl;
    }
  }
#else
  for (i = 0; i < m; i++)
     for (j = 0; j < n; j++) {
        for (k = i+1; k < m; k++)
           B[i][j] += A[k][i] * B[k][j];
        B[i][j] = alpha * B[i][j];
     }
#endif
#pragma endscop

}
